export function verifyIndependentSynonymReview(read=readFileSync){
 const successor=verifyWritingCopyRelease(read),currentRead=read;read=file=>readBeforeWritingCopy(file,successor,currentRead);
 const json=f=>JSON.parse(read(f)),r=json('docs/klink-owner-release-synonym-independent-review-20261101.json');
 assert.equal(r.approvedBy,'Nico');assert(r.publicationApproved&&r.appearanceUnchanged);assert(r.userRequest.includes('onafhankelijke taalreview')&&r.userRequest.includes('Synoniemen'));assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort(lines(git('diff','--name-only',base,successor.baselineSourceCommit,'--',...roots)));assert.deepEqual(changed,allowed);assert.deepEqual(changed,r.changedFiles);assert.deepEqual(sort(Object.keys(r.files)),changed);for(const[f,h]of Object.entries(r.files))assert.equal(sha(read(f)),h,f);for(const[f,h]of Object.entries(r.evidenceFiles))assert.equal(sha(read(f)),h,f);
 assert.equal(git('diff','--name-only',base,successor.baselineSourceCommit,'--','app','components','hooks','lib','public','db','drizzle','.github','AGENTS.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','package.json','package-lock.json','vite.config.ts','wrangler.jsonc').length,0,'Preserve appearance, audio, routes, storage, dependencies and workflows');assert.deepEqual(lines(git('diff','--name-only',base,successor.baselineSourceCommit,'--','data')),['data/klink-synonyms.json']);
 const bank=json('data/klink-synonyms.json'),before=JSON.parse(git('show',base+':data/klink-synonyms.json')),review=json(folder+'content-review.json'),changes=json(folder+'changes.json');
 assert.deepEqual({...bank,entries:before.entries},before);assert.equal(bank.entries.length,225);assert.equal(review.rows.length,225);assert.equal(review.answerCardsReviewed,900);assert.equal(review.directionsReviewed,450);assert.equal(review.bankSha256,sha(read('data/klink-synonyms.json')));assert.equal(review.independentHumanReview,false);assert.equal(review.individualCefrValidated,false);assert.equal(review.classroomPilot,'open');assert.equal(changes.length,86);assert.equal(review.changedRows,86);
 const actualChanges=[];
 for(const e of bank.entries){const old=before.entries.find(x=>x.id===e.id),row=review.rows.find(x=>x.id===e.id);assert(old&&row);const current={...e},original={...old};for(const k of ['context','reverseContext']){delete current[k];delete original[k];}assert.deepEqual(current,original);
  for(const k of['id','word','synonym','options','minimumLevel','levels','active','collectionId','collectionTitle','source','sourceWords','review'])assert.deepEqual(e[k],old[k],e.id+':'+k);
  for(const k of['word','synonym','options','context','reverseContext','active'])assert.deepEqual(row[k],e[k]);for(const k of review.dimensions)assert.equal(row[k],true);assert.equal(row.uniqueCorrectAnswer,e.active);assert.equal(e.options.length,4);assert.equal(new Set(e.options).size,4);assert.equal(e.options.filter(o=>o===e.synonym).length,1);assert(!e.options.includes(e.word));
  if('context'in e){assert(e.context.includes(e.word));assert(e.reverseContext.includes(e.synonym));assert(e.context.split(/\s+/).length<=18&&e.reverseContext.split(/\s+/).length<=18);}
  if(JSON.stringify(e)!==JSON.stringify(old)){actualChanges.push(e.id);const change=changes.find(x=>x.id===e.id);assert(change);assert.deepEqual(change.changedFields,['context','reverseContext']);assert.deepEqual(change.after,{context:e.context,reverseContext:e.reverseContext});assert(e.active);}
 }
 assert.deepEqual(sort(actualChanges),sort(changes.map(x=>x.id)));assert.equal(bank.entries.filter(e=>e.active).length,200);
 for(const[level,count,amended]of[['a1',17,9],['a2',45,27],['b1',163,50]]){
  const first=json(folder+'independent-'+level+'.json'),final=json(folder+'final-'+level+'.json'),ids=bank.entries.filter(e=>e.minimumLevel===level).map(e=>e.id);assert.equal(ids.length,count);assert.equal(first.sourceBankSha256,json(folder+'baseline.json').bankSha256);assert.deepEqual(sort([...first.reviewedIds]),sort(ids));assert.equal(first.results.length,count);assert.deepEqual(sort(first.results.map(x=>x.id)),sort(ids));
  assert.equal(final.sourceBankSha256,review.bankSha256);assert.equal(final.independentHumanReview,false);assert(final.allChangedQuestionsApproved);assert.deepEqual(final.unresolved,[]);assert.equal(final.rows.length,amended);assert.deepEqual(sort([...final.checkedIds]),sort(changes.filter(x=>x.level===level).map(x=>x.id)));for(const row of final.rows)for(const k of['approved','naturalness','grammar','spelling','levelSuitable','uniqueCorrectAnswer','bothDirectionsReviewed'])assert.equal(row[k],true);
 }
 const spelling=json(folder+'spelling-check.json');assert.equal(spelling.entriesChecked,225);assert.equal(spelling.fieldsChecked,1538);assert(spelling.reviewCompleted);assert.deepEqual(spelling.warnings,[]);assert.deepEqual(spelling.unresolved,[]);
 const inventory=json(folder+'audio-inventory.json');assert.equal(inventory.length,380);assert.equal(inventory.reduce((n,c)=>n+c.uses.length,0),400);for(const c of inventory){assert.equal(sha(read('public'+c.src)),c.sha256);for(const k of['artist','album_artist','publisher'])assert.equal(c.metadata[k],'Taalroute');}assert.equal(r.newRecordings,0);
 const browser=json(folder+'local/browser-checks.json');assert.equal(browser.checks.length,800);assert.equal(browser.layouts.length,72);assert.equal(browser.modes.length,26);assert.equal(browser.decoded.length,2);assert(browser.decoded.every(x=>x.clips.length===380));assert.equal(browser.preserved.length,8);assert(browser.preserved.every(x=>x.pixelIdentical));assert.deepEqual(browser.errors,[]);
 const worker=json(folder+'worker-preview-checks.json'),keyboard=json(folder+'keyboard-checks.json');assert.equal(worker.checks.length,172);assert.equal(worker.modes.length,24);assert.deepEqual(worker.errors,[]);assert.equal(keyboard.checks.length,12);assert.deepEqual(keyboard.errors,[]);assert(keyboard.checks.every(c=>c.wrongEnter&&c.correctEnter&&c.noAutomaticAdvance&&c.nextEnter&&c.resume));
 const integrated=json(folder+'integrated/browser-checks.json');assert.equal(integrated.checks.length,800);assert.equal(integrated.layouts.length,72);assert.equal(integrated.modes.length,26);assert.equal(integrated.decoded.length,2);assert(integrated.decoded.every(x=>x.clips.length===380));assert.equal(integrated.preserved.length,8);assert(integrated.preserved.every(x=>x.pixelIdentical));assert.deepEqual(integrated.errors,[]);
 const checks=json(folder+'verification.json');for(const k of['types','lint','unit','build','allPairs','allAnswerOptions','bothDirections','allContexts','audioMetadata','browserAndKeyboard','progressPreserved','appearancePreserved','localOnly'])assert.equal(checks[k],true,k);assert.equal(checks.independentHumanReview,false);
 const backup=json(folder+'backup.json');assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);assert(backup.parts.every(p=>p.verified&&p.fullReadback&&p.zipIntegrity&&p.driveId));return {...r,successor};
}
export function readBeforeIndependentSynonymReview(file,r,read=readFileSync){return r.changedFiles.includes(file)?git('show',base+':'+file):readBeforeWritingCopy(file,r.successor,read);}
